#!/bin/sh
set -eu
plugin_root=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
# runtime.json contains local paths only, never credentials. It is generated by
# setup.mjs and copied with the installed package. Prefer the exact configured
# Node runtime; a GUI host need not have a shell/nvm PATH.
node_bin=${GOOGLE_CHAT_NODE:-}
if [ -z "$node_bin" ]; then
  for candidate in /opt/homebrew/bin/node /usr/local/bin/node "$HOME"/.nvm/versions/node/*/bin/node; do
    if [ -x "$candidate" ]; then node_bin=$candidate; fi
  done
fi
if [ -z "$node_bin" ]; then
  echo 'Node.js 22+ is required. Run the plugin setup guide.' >&2
  exit 1
fi
exec "$node_bin" "$plugin_root/dist/launch.js"
